n/// color||Color|0\n$--avatar-background-color: #C0C4CC !default;\n/// fontSize||Font Size|1\n$--avatar-text-font-size: 14px !default;\n/// fontSize||Font Size|1\n$--avatar-icon-font-size: 18px !default;\n/// borderRadius||Border|2\n$--avatar-border-radius: $--border-radius-base !default;\n/// size|1|Avatar Size|3\n$--avatar-large-size: 40px !default;\n/// size|1|Avatar Size|3\n$--avatar-medium-size: 36px !default;\n/// size|1|Avatar Size|3\n$--avatar-small-size: 28px !default;\n\n/* Break-point\n--------------------------*/\n$--sm: 768px !default;\n$--md: 992px !default;\n$--lg: 1200px !default;\n$--xl: 1920px !default;\n\n$--breakpoints: (\n    'xs' : (max-width: $--sm - 1),\n    'sm' : (min-width: $--sm),\n    'md' : (min-width: $--md),\n    'lg' : (min-width: $--lg),\n    'xl' : (min-width: $--xl)\n);\n\n$--breakpoints-spec: (\n    'xs-only' : (max-width: $--sm - 1),\n    'sm-and-up' : (min-width: $--sm),\n    'sm-only': \"(min-width: #{$--sm}) and (max-width: #{$--md - 1})\",\n    'sm-and-down': (max-width: $--md - 1),\n    'md-and-up' : (min-width: $--md),\n    'md-only': \"(min-width: #{$--md}) and (max-width: #{$--lg - 1})\",\n    'md-and-down': (max-width: $--lg - 1),\n    'lg-and-up' : (min-width: $--lg),\n    'lg-only': \"(min-width: #{$--lg}) and (max-width: #{$--xl - 1})\",\n    'lg-and-down': (max-width: $--xl - 1),\n    'xl-only' : (min-width: $--xl),\n);\n\n"],sourceRoot:""}]);const l=a},599:(e,t,n)=>{"use strict";n.d(t,{Z:()=>l});var r=n(4015),o=n.n(r),i=n(3645),a=n.n(i)()(o());a.push([e.id,'@charset "UTF-8";.task{background-color:#fff;border-bottom:1px solid #dcdfe6;justify-content:space-between;padding:1em}.task:last-of-type{border:0}.task .task-controls{align-items:center;display:flex;justify-content:flex-end}.task .task-controls .el-button{display:block;font-size:.82rem;padding:10px 0;width:100%}.task .task-controls.pin{display:block;justify-content:center;width:auto}.task .task-info{display:flex;flex-direction:column;max-width:75%}.task .task-